<?php
session_start(); include 'conn.php'; include 'auth.php'; require_roles(['owner','buyer']);
$uid=(int)$_SESSION['user_id']; $role=$_SESSION['role']; $selected_tree=(int)($_GET['tree_id']??0);
$tree_types=mysqli_query($con,"SELECT tree_type_id,type_name,unit_price FROM tree_types WHERE is_active=1 ORDER BY type_name");
if ($role==='owner') $stocks=mysqli_query($con,"SELECT t.tree_id,t.species,t.quantity,t.growth_status,p.plantation_name FROM trees t JOIN plantations p ON p.plantation_id=t.plantation_id WHERE p.owner_id=$uid AND t.quantity>0 AND t.growth_status IN ('mature','ready_for_harvest') ORDER BY p.plantation_name,t.species");
else $stocks=mysqli_query($con,"SELECT t.tree_id,t.species,(t.sale_quantity-t.reserved_quantity) available,p.plantation_name,u.full_name owner_name FROM trees t JOIN plantations p ON p.plantation_id=t.plantation_id JOIN users u ON u.user_id=p.owner_id WHERE t.growth_status IN ('mature','ready_for_harvest') AND t.sale_quantity>t.reserved_quantity AND t.unit_price>0 ORDER BY t.species");
$page_title='New forest request'; include 'includes/header.php'; include 'includes/navbar.php';
?>
<h1 class="page-title h2 mb-3"><?= $role==='buyer'?'Request available trees':'New forest request' ?></h1><div class="card border-0 shadow-sm"><div class="card-body p-4"><form method="post" action="request_save.php"><div class="row g-3">
<?php if($role==='owner'): ?><div class="col-md-6"><label class="form-label">Request type</label><select id="requestType" class="form-select" name="request_type" required><option value="plant_license">Permission to plant</option><option value="cut_license">Permission to cut / sell</option></select></div><?php else: ?><input type="hidden" name="request_type" value="buy_trees"><?php endif; ?>
<div id="typeField" class="col-md-6 <?= $role==='buyer'?'d-none':'' ?>"><label class="form-label">Tree type registered by NAEB</label><select id="treeType" class="form-select" name="tree_type_id"><option value="">Select tree type</option><?php while($tt=mysqli_fetch_assoc($tree_types)): ?><option value="<?= (int)$tt['tree_type_id'] ?>"><?= e($tt['type_name']) ?> — <?= e(money($tt['unit_price'])) ?></option><?php endwhile; ?></select></div>
<div id="stockField" class="col-12 <?= $role==='owner'?'d-none':'' ?>"><label class="form-label"><?= $role==='buyer'?'Approved trees available to buy':'Your mature tree stock' ?></label><select id="treeStock" class="form-select" name="tree_id"><option value="">Select available trees</option><?php while($s=mysqli_fetch_assoc($stocks)): $available=$role==='buyer'?(int)$s['available']:(int)$s['quantity']; ?><option value="<?= (int)$s['tree_id'] ?>" <?= $selected_tree===(int)$s['tree_id']?'selected':'' ?>><?= e($s['species'].' — '.$s['plantation_name'].($role==='buyer'?' — '.$s['owner_name']:'').' — '.number_format($available).' available') ?></option><?php endwhile; ?></select></div>
<div class="col-md-4"><label class="form-label">Quantity of trees</label><input class="form-control" type="number" min="1" name="quantity" required></div><div id="areaField" class="col-md-4 <?= $role==='buyer'?'d-none':'' ?>"><label class="form-label">Area size (ha)</label><input class="form-control" type="number" min="0.01" step="0.01" name="area_size"></div><div class="col-12"><label class="form-label">Reason / notes</label><textarea class="form-control" name="reason" rows="4" required></textarea></div></div><div class="mt-4"><button class="btn btn-success" name="save">Submit for forestry approval</button> <a class="btn btn-light" href="requests.php">Cancel</a></div></form></div></div>
<?php if($role==='owner'): ?><script>const rt=document.getElementById('requestType'),tf=document.getElementById('typeField'),sf=document.getElementById('stockField'),af=document.getElementById('areaField'),tt=document.getElementById('treeType'),ts=document.getElementById('treeStock');function sync(){const plant=rt.value==='plant_license';tf.classList.toggle('d-none',!plant);sf.classList.toggle('d-none',plant);af.classList.toggle('d-none',!plant);tt.required=plant;ts.required=!plant;}rt.addEventListener('change',sync);sync();</script><?php endif; include 'includes/footer.php'; ?>
